import random, json, importlib
import orig, new
random.seed(0)
mismatch=0
for t in range(200000):
    def rnd_int():
        # mix of normal, edge, negative, huge, non-int, missing
        k=random.random()
        if k<0.5: return random.randint(-50,300)
        return random.randint(-1000,2000)
    w = random.choice([0,1,2,3,50,101,'x',None,1.5])
    h = random.choice([0,1,2,50,101,'y',2])
    cs = random.choice([0,1,2,10,25,'z',3])
    fv = random.choice([0,-1,5,'a',None,2.5])
    obs=[]
    for _ in range(random.randint(0,12)):
        if random.random()<0.15: obs.append('junk'); continue
        d={}
        for f in ('x','y','value','quality'):
            if random.random()<0.1: continue
            v=random.choice([0,1,5,19,20,25,99,101,-3,random.randint(-500,500),'n',None,2.7])
            d[f]=v
        obs.append(d)
    raw={'grid':{'width':w,'height':h,'cell_size':cs},'observations':obs,'fill_value':fv}
    if random.random()<0.05: raw.pop('grid',None) or raw.update({'grid2':1})
    if random.random()<0.03: raw['observations']='notalist'
    if random.random()<0.03: raw.pop('fill_value',None)
    if random.random()<0.05: raw['grid']='bad'
    try:
        a=orig.accumulate_grid(raw)
    except Exception as e:
        a=('EXC',type(e).__name__,str(e))
    try:
        b=new.accumulate_grid(raw)
    except Exception as e:
        b=('EXC',type(e).__name__,str(e))
    if a!=b:
        mismatch+=1
        if mismatch<=10:
            print('MISMATCH', json.dumps(raw)); print(' orig',a); print(' new ',b)
print('done. mismatches:',mismatch)
"

