=== FINAL FILE ===
from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    """Accumulate grid observations into per-cell averages with quality flags.

    Merges raw observations into a grid: each observation lands in a cell based
    on its (x, y) coordinates, values are averaged, and cells carry quality
    flags. Returns a result dict; on invalid input returns {"ok": False, ...}.
    """
    if not isinstance(raw, dict):
        return _fail("malformed input")
    try:
        grid = raw["grid"]
        observations = raw["observations"]
        fill_value = raw["fill_value"]
    except KeyError:
        return _fail("missing field")
    if not isinstance(grid, dict):
        return _fail("bad grid")

    spec = _grid_spec(grid)
    if not isinstance(spec, tuple):
        return _fail(spec)
    width, height, cell_size = spec
    if not isinstance(fill_value, int):
        return _fail("bad fill value")
    if not isinstance(observations, list):
        return _fail("bad observations")

    sums = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        if _reject_observation(obs):
            return _fail("bad observation")
        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue

        col, ok = _grid_coord(obs["x"], width, cell_size, tolerance)
        if ok is False:
            dropped = dropped + 1
            continue
        row, ok = _grid_coord(obs["y"], height, cell_size, tolerance)
        if ok is False:
            dropped = dropped + 1
            continue

        if _accumulate(sums, counts, degraded, row, col, obs):
            saturated = saturated + 1

    cells = _averaged_rows(sums, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _fail(error: str) -> dict:
    return {"ok": False, "error": error}


def _grid_spec(grid: dict):
    """Validate a grid spec; return (width, height, cell_size) or an error string."""
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return "bad grid"
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or not 1 <= width <= MAX_DIM:
        return "bad width"
    if not isinstance(height, int) or not 1 <= height <= MAX_DIM:
        return "bad height"
    if not isinstance(cell_size, int) or cell_size < 1:
        return "bad cell size"
    return (width, height, cell_size)


def _reject_observation(obs) -> bool:
    """Return True if the observation is malformed and should abort the run."""
    if not isinstance(obs, dict):
        return True
    for field in ("x", "y", "value", "quality"):
        if field not in obs or not isinstance(obs[field], int):
            return True
    return not 0 <= obs["quality"] <= 100


def _grid_coord(coord: int, limit: int, cell_size: int, tolerance: int):
    """Map a coordinate to a cell index, or signal that it should be dropped."""
    if coord < 0:
        return None, False
    index = coord // cell_size
    if index >= limit:
        if coord - limit * cell_size < tolerance:
            index = limit - 1
        else:
            return None, False
    return index, True


def _accumulate(sums, counts, degraded, row, col, obs) -> bool:
    """Add an observation to a cell; return True if it was skipped as saturated."""
    key = (row, col)
    if counts.get(key, 0) >= SATURATION_LIMIT:
        return True
    sums[key] = sums.get(key, 0) + obs["value"]
    counts[key] = counts.get(key, 0) + 1
    if obs["quality"] < GOOD_QUALITY:
        degraded[key] = True
    return False


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    def average(key):
        return sums[key] // counts[key] if key in counts else fill_value

    return [[average((row, col)) for col in range(width)] for row in range(height)]


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    def flag(key):
        if key not in counts:
            return "empty"
        return "degraded" if key in degraded else "good"

    return [[flag((row, col)) for col in range(width)] for row in range(height)]


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    parts = (
        ("cells", total_cells),
        ("filled", filled),
        ("dropped", dropped),
        ("rejected", rejected),
        ("saturated", saturated),
        ("coverage", coverage),
    )
    return ";".join(f"{name}={value}" for name, value in parts)
